-- q9113: node=2010 (课文1《大青树下的小学》)
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2010, '语文', '三年级', '填空', 2, '{"stem": "根据课文内容，在括号内填上合适的词语。\n（　　）的服装　（　　）的小鸟　（　　）的小学\n（　　）的教室　（　　）的国旗　（　　）的老师\n（　　）的铜钟　（　　）的枝干　（　　）的墙\n（　　）的声音　（　　）游戏", "options": null}', '鲜艳（美丽）的服装、欢快的小鸟、美丽的小学、明亮的教室、鲜艳的国旗、敬爱的老师、古老的铜钟、粗壮的枝干、洁白的墙、悦耳的声音、快乐地游戏', '本题考查课文词语搭配，均出自《大青树下的小学》原文。', 'paper', '"[\"词语积累\", \"课文1\", \"第一单元\"]"', NULL, 0, 1);

-- q9114: node=2010 (课文1《大青树下的小学》)
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2010, '语文', '三年级', '填空', 3, '{"stem": "照样子，写句子。\n例1：同学们向在校园里欢唱的小鸟打招呼，向敬爱的老师问好，向高高飘扬的国旗敬礼。（排比句）\n仿写：", "options": null}', '答案不唯一。示例：花儿向太阳微笑，向春风点头，向蝴蝶招手。', '排比句仿写，要求三个"向……"结构，内容积极向上。', 'paper', '"[\"仿写句子\", \"课文1\", \"第一单元\"]"', NULL, 0, 1);

-- q9115: node=2010 (课文1《大青树下的小学》)
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2010, '语文', '三年级', '填空', 3, '{"stem": "照样子，写句子。\n例2：早晨，从山坡上，从坪坝里，从一条条开着绒花和太阳花的小路上，走来了许多小学生。（排比句）\n仿写：", "options": null}', '答案不唯一。示例：春天，从田野里，从枝头上，从一条条解冻的小溪旁，飞来了许多小鸟。', '排比句仿写，要求三个"从……"结构，描写场景。', 'paper', '"[\"仿写句子\", \"课文1\", \"第一单元\"]"', NULL, 0, 1);

