-- q9122: node=2013 (课文4《古诗三首》)
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2013, '语文', '三年级', '填空', 3, '{"stem": "写出下列加点字的意思。\n1. 湖光秋月两相和：____\n2. 远上寒山石径斜：____\n3. 白云生处有人家：____\n4. 知有儿童挑促织：____\n5. 停车坐爱枫林晚：____\n6. 霜叶红于二月花：____", "options": null}', '1. 和：和谐、融洽\n2. 斜：倾斜、弯曲\n3. 生处：产生、升起的地方\n4. 挑：逗弄、拨动\n5. 坐：因为\n6. 于：比', '本题考查《望洞庭》《山行》《夜书所见》三首古诗中加点字词的理解。"坐"是古今异义，意为"因为"。', 'paper', '"[\"古诗理解\", \"课文4\", \"第二单元\"]"', NULL, 0, 1);

-- q9123: node=2013 (课文4《古诗三首》)
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2013, '语文', '三年级', '填空', 2, '{"stem": "古诗默写并完成练习。\n《望洞庭》　[唐]刘禹锡\n湖光秋月两相和，____________。遥望洞庭山水翠，____________。\n《山行》　[唐]杜牧\n远上寒山石径斜，____________。停车坐爱枫林晚，____________。\n《夜书所见》　[宋]叶绍翁\n萧萧梧叶送寒声，____________。知有儿童挑促织，____________。", "options": null}', '《望洞庭》：潭面无风镜未磨；白银盘里一青螺\n《山行》：白云生处有人家；霜叶红于二月花\n《夜书所见》：江上秋风动客情；夜深篱落一灯明', '三首古诗均为部编版三年级上册第二单元课文。《望洞庭》写洞庭湖月夜美景，《山行》写深秋山林红叶，《夜书所见》写秋夜客居思乡。', 'paper', '"[\"古诗默写\", \"课文4\", \"第二单元\"]"', NULL, 0, 1);

-- q9124: node=2014 (课文5《铺满金色巴掌的水泥道》)
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2014, '语文', '三年级', '填空', 2, '{"stem": "按要求写出下面词语的近反义词。\n近义词：明朗——（　　）　增添——（　　）　潮湿——（　　）　愉快——（　　）\n反义词：潮湿——（　　）　规则——（　　）　仔细——（　　）　湿漉漉——（　　）", "options": null}', '近义词：明朗——明亮/晴朗；增添——增加；潮湿——湿润；愉快——高兴/快乐\n反义词：潮湿——干燥；规则——随意/凌乱；仔细——马虎/粗心；湿漉漉——干巴巴', '本题考查《铺满金色巴掌的水泥道》一课的近反义词积累。', 'paper', '"[\"近反义词\", \"课文5\", \"第二单元\"]"', NULL, 0, 1);

-- q9125: node=2015 (课文6《秋天的雨》)
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2015, '语文', '三年级', '填空', 2, '{"stem": "根据课文内容，在括号内填上合适的词语。\n（　　）的枫叶　（　　）的钥匙\n（　　）的夏天　（　　）的海洋\n（　　）的菊花　（　　）的秋天\n（　　）的气味　一（　　）邮票", "options": null}', '红红的枫叶、金黄的钥匙、炎热的夏天、彩色的海洋、美丽的菊花、丰收的秋天、好闻的气味、一枚邮票', '本题考查《秋天的雨》课文词语搭配。钥匙比喻秋雨，文中"秋天的雨，有一盒五彩缤纷的颜料"。', 'paper', '"[\"词语积累\", \"课文6\", \"第二单元\"]"', NULL, 0, 1);

-- q9126: node=2016 (课文7《听听，秋的声音》)
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2016, '语文', '三年级', '填空', 2, '{"stem": "按要求完成练习。\n（秋高气爽）有关秋天的词语：____、____、____\n（汪汪）描写声音的词语：____、____、____", "options": null}', '有关秋天的词语：秋色宜人、一叶知秋、秋风习习\n描写声音的词语：哗哗、喵喵、叽叽喳喳', '本题考查词语积累。秋天相关词语和拟声词仿写，答案不唯一。', 'paper', '"[\"词语积累\", \"课文7\", \"第二单元\"]"', NULL, 0, 1);

-- q9127: node=2017 (课文8《总也倒不了的老屋》)
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2017, '语文', '三年级', '填空', 3, '{"stem": "写出对应读音的字，并填空。\n【bèi】（　　）壳　（　　）子　有（　　）而来\n【bǎo】（　　）满　（　　）石　（　　）经风霜\n【zài】（　　）次　存（　　）", "options": null}', '【bèi】贝壳、被子、有备而来\n【bǎo】饱满、宝石、饱经风霜\n【zài】再次、存在', '同音字辨析填空。"备"在"有备而来"中意为准备。', 'paper', '"[\"同音字\", \"课文8\", \"第三单元\"]"', NULL, 0, 1);

-- q9128: node=2018 (课文9《犟龟》)
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2018, '语文', '三年级', '填空', 2, '{"stem": "先把四字词语补充完整，再选词填空。\n路途（　）（　）　满怀（　）（　）\n居（　）临（　）　哈哈（　）（　）\n日（　）不（　）　（　）（　）糊糊\n1. 我们站在山顶上眺望，美景尽收眼底，有一种_______的感觉。\n2. 他_______地走上演讲台，准备向全校师生分享自己的学习经验与心得。", "options": null}', '路途（遥）（远）　满怀（信）（心）\n居（高）临（下）　哈哈（大）（笑）\n日（夜）不（息）　（糊）（里）糊糊\n1. 居高临下\n2. 满怀信心', '四字词语补充及选词填空，考查词语积累与语境运用。', 'paper', '"[\"词语补充\", \"课文9\", \"第三单元\"]"', NULL, 0, 1);

-- q9129: node=2019 (课文10《小狗学叫》)
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2019, '语文', '三年级', '填空', 2, '{"stem": "照样子，写词语。\n孤零零（ABB式）：____、____、____\n不知不觉（ABAC式）：____、____、____\n形容笑的词语（哈哈大笑）：____、____、____\n含数字的词语（一本正经）：____、____、____", "options": null}', 'ABB式：绿油油、红彤彤、白花花\nABAC式：无边无际、一模一样、自言自语\n形容笑的词语：捧腹大笑、眉开眼笑、喜笑颜开\n含数字的词语：三心二意、四面八方、五光十色', '词语仿写，答案不唯一，考查词语结构规律。', 'paper', '"[\"词语仿写\", \"课文10\", \"第三单元\"]"', NULL, 0, 1);

-- q9130: node=2020 (课文11《宝葫芦的秘密》)
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2020, '语文', '三年级', '填空', 2, '{"stem": "照样子，写词语。\n1. 平平常常（AABB式）：____、____、____\n2. 可怜巴巴（ABCC式）：____、____、____\n3. 又瘦又长（又X又X）：____、____、____", "options": null}', '1. AABB式：明明白白、高高兴兴、快快乐乐\n2. ABCC式：得意洋洋、白发苍苍、小心翼翼\n3. 又X又X：又大又圆、又香又甜、又高又壮', '词语结构仿写，答案不唯一。', 'paper', '"[\"词语仿写\", \"课文11\", \"第三单元\"]"', NULL, 0, 1);

-- q9131: node=2021 (课文12《在牛肚子里旅行》)
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2021, '语文', '三年级', '填空', 2, '{"stem": "照样子，写词语。\n细嚼慢咽（含近义词的成语）：____、____、____\n蹭来蹭去（ABAC式的词语）：____、____、____\n笑眯眯（ABB式的词语）：____、____、____", "options": null}', '含近义词的成语：左顾右盼、东张西望、南辕北辙\nABAC式：走来走去、飞来飞去、跳来跳去\nABB式：笑呵呵、乐呵呵、亮晶晶', '词语结构仿写，答案不唯一。', 'paper', '"[\"词语仿写\", \"课文12\", \"第四单元\"]"', NULL, 0, 1);

-- q9132: node=2022 (课文13《一块奶酪》)
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2022, '语文', '三年级', '填空', 2, '{"stem": "先把词语补充完整，再选词填空。\n七上（　）（　）　争（　）恐（　）\n（　）面（　）方\n1. 一群昆虫从_______飞到小蜜蜂的花蜜店门口，它们_______地涌入店里。\n2. 请写出含有反义词的四字词语：_______", "options": null}', '七上（八）（下）　争（先）恐（后）\n（四）面（八）方\n1. 四面八方、争先恐后\n2. 含反义词的四字词语：大惊小怪、大同小异、左邻右舍', '四字词语补充及选词填空，考查含反义词的成语积累。', 'paper', '"[\"词语补充\", \"课文13\", \"第四单元\"]"', NULL, 0, 1);

-- q9133: node=2023 (课文14《搭船的鸟》)
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2023, '语文', '三年级', '填空', 2, '{"stem": "照样子，写词语。\n静悄悄（ABB式词语）：____、____、____\n沙啦沙啦（拟声词）：____、____、____\n鼠目寸光（含动物名称的成语）：____、____、____\n鸟尽弓藏（含“鸟”字的成语）：____、____、____", "options": null}', 'ABB式：亮晶晶、绿油油、红彤彤\n拟声词：叮叮当当、滴滴答答、哗啦哗啦\n含动物名称的成语：狐假虎威、鸡飞狗跳、牛刀小试\n含“鸟”字的成语：鸟语花香、笨鸟先飞、惊弓之鸟', '词语结构仿写，答案不唯一。', 'paper', '"[\"词语仿写\", \"课文14\", \"第四单元\"]"', NULL, 0, 1);

-- q9134: node=2024 (课文15《金色的草地》)
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2024, '语文', '三年级', '填空', 2, '{"stem": "写出下列词语的近反义词。\n近义词：玩耍——（　　）　仔细——（　　）\n有趣——（　　）　盛开——（　　）\n假装——（　　）　观察——（　　）\n一本正经——（　　）　喜爱——（　　）\n反义词：盛开——（　　）　有趣——（　　）\n合拢——（　　）　常常——（　　）\n快乐——（　　）　引人注目——（　　）", "options": null}', '近义词：玩耍——嬉戏；仔细——认真；有趣——有意思是；盛开——绽放；假装——伪装；观察——观看；一本正经——郑重其事；喜爱——喜欢\n反义词：盛开——凋谢；有趣——无聊；合拢——张开；常常——偶尔；快乐——悲伤；引人注目——毫不起眼', '本题考查《金色的草地》一课的近反义词积累。', 'paper', '"[\"近反义词\", \"课文15\", \"第四单元\"]"', NULL, 0, 1);

-- q9135: node=2025 (课文16《富饶的西沙群岛》)
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2025, '语文', '三年级', '填空', 2, '{"stem": "照样子，完成词语练习。\n（　　）的花朵　（　　）的条纹\n（　　）的鸟类　风景（　　）\n（　　）的鹿角　（　　）的树林\n（　　）的肥料　物产（　　）\n（深蓝淡青）表示颜色的二字词语：____、____、____", "options": null}', '美丽的花朵、彩色的条纹、珍贵的鸟类、风景优美、枝杈的鹿角、茂密的树林、丰富的肥料、物产丰富\n表示颜色的二字词语：碧绿、金黄、火红', '本题考查《富饶的西沙群岛》课文词语搭配及颜色词积累。', 'paper', '"[\"词语积累\", \"课文16\", \"第五单元\"]"', NULL, 0, 1);

-- q9136: node=2026 (课文17《海滨小城》)
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2026, '语文', '三年级', '填空', 2, '{"stem": "根据课文内容，在括号里填入合适的词语。\n（　　）的军舰　（　　）的虾和蟹\n一（　　）沙滩　（　　）的帆船\n（　　）的海螺　（　　）地躺\n（　　）的大海　（　　）的鱼\n一（　　）庭院", "options": null}', '白色的军舰、新鲜的虾和蟹、一片沙滩、彩色的帆船、美丽的海螺、静静地躺、蓝色的大海、活泼的鱼、一座庭院', '本题考查《海滨小城》课文词语搭配和量词运用。', 'paper', '"[\"词语积累\", \"课文17\", \"第五单元\"]"', NULL, 0, 1);

-- q9137: node=2027 (课文18《美丽的小兴安岭》)
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2027, '语文', '三年级', '填空', 2, '{"stem": "把下面词语补充完整，并选词填空。\n（　）严（　）实　各种（　）（　）\n酸（　）可（　）\n1. 学校的器材室里摆满了_______的体育用品。\n2. 这道糖醋排骨做得_______，让人一吃就停不下来。", "options": null}', '（严）严（密）实　各种（各）（样）\n酸（甜）可（口）\n1. 各种各样\n2. 严严实实', '四字词语补充及选词填空，考查《美丽的小兴安岭》一课词语积累。', 'paper', '"[\"词语补充\", \"课文18\", \"第五单元\"]"', NULL, 0, 1);

-- q9138: node=2028 (课文19《香港，璀璨的明珠》)
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2028, '语文', '三年级', '填空', 2, '{"stem": "根据课文内容，在括号里填入合适的词语。\n（　　）的灯光　（　　）的焰火\n（　　）的明珠　（　　）的商人\n（　　）的游客　（　　）的贸易活动\n（　　）的车灯　（　　）的贸易港城\n（　　）的维多利亚港", "options": null}', '璀璨的灯光、绚丽的焰火、璀璨的明珠、精明的商人、来自各地的游客、繁忙的贸易活动、流动的车灯、繁华的贸易港城、美丽的维多利亚港', '本题考查《香港，璀璨的明珠》课文词语搭配。', 'paper', '"[\"词语积累\", \"课文19\", \"第五单元\"]"', NULL, 0, 1);

-- q9139: node=2029 (课文20《古诗三首》)
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2029, '语文', '三年级', '填空', 2, '{"stem": "古诗默写。\n《鹿柴》　[唐]王维\n空山不见人，____________。返景入深林，____________。\n《望天门山》　[唐]李白\n____________，____________。____________，____________。\n《饮湖上初晴后雨》　[宋]苏轼\n____________，____________。____________，____________。", "options": null}', '《鹿柴》：但闻人语响；复照青苔上\n《望天门山》：天门中断楚江开，碧水东流至此回。两岸青山相对出，孤帆一片日边来。\n《饮湖上初晴后雨》：水光潋滟晴方好，山色空蒙雨亦奇。欲把西湖比西子，淡妆浓抹总相宜。', '三首古诗均为部编版三年级上册第六单元课文。《鹿柴》写空山幽静，《望天门山》写天门山险峻，《饮湖上初晴后雨》写西湖美景。', 'paper', '"[\"古诗默写\", \"课文20\", \"第六单元\"]"', NULL, 0, 1);

-- q9140: node=2029 (课文20《古诗三首》)
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2029, '语文', '三年级', '填空', 3, '{"stem": "根据所学填空。\n1.《鹿柴》描绘了鹿柴附近山深林密的幽静景色，渲染出一种清冷空寂的意境，表现了诗人_______的心境。\n2.《望天门山》描绘了波澜壮阔的长江从天门山中间奔流东去的雄奇景色，表达了诗人_______之情。\n3.《饮湖上初晴后雨》描绘了西湖在不同天气下呈现的不同风姿，表达了诗人_______之情。", "options": null}', '1. 闲适恬淡、寄情山水\n2. 对祖国大好河山的热爱和赞美\n3. 对西湖美景的喜爱和赞美', '本题考查三首古诗的主旨情感理解。', 'paper', '"[\"古诗理解\", \"课文20\", \"第六单元\"]"', NULL, 0, 1);

-- q9141: node=2030 (课文21《大自然的声音》)
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2030, '语文', '三年级', '填空', 2, '{"stem": "读一读，连一连。\n轻轻柔柔的——乐曲\n轻快的——海洋大合唱\n雄伟的——音乐会\n波澜壮阔的——山中小曲\n热闹的——声音\n叽叽喳喳的——鸟叫", "options": null}', '轻轻柔柔的——声音\n轻快的——山中小曲\n雄伟的——乐曲\n波澜壮阔的——海洋大合唱\n热闹的——音乐会\n叽叽喳喳的——鸟叫', '本题考查《大自然的声音》一课短语搭配。课文把大自然比作音乐家。', 'paper', '"[\"短语搭配\", \"课文21\", \"第六单元\"]"', NULL, 0, 1);

-- q9142: node=2031 (课文22《读不完的大书》)
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2031, '语文', '三年级', '填空', 2, '{"stem": "根据所学，在括号内填入合适的词语。\n（　　）的东西　（　　）的趣味\n（　　）的细语　（　　）的天空\n（　　）的棕榈树　（　　）的大地\n（　　）的奥秘", "options": null}', '好玩的东西、无穷的趣味、温柔的细语、广阔的天空、高大的棕榈树、辽阔的大地、无尽的奥秘', '本题考查《读不完的大书》课文词语搭配。', 'paper', '"[\"词语积累\", \"课文22\", \"第六单元\"]"', NULL, 0, 1);

-- q9143: node=2032 (课文23《司马光》)
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2032, '语文', '三年级', '填空', 3, '{"stem": "先解释加点字词的意思，再解释整句话的意思。\n1. 群儿戏于庭。\n释义：____\n2. 一儿登瓮，足跌没水中。\n释义：____\n3. 众皆弃去，光持石击瓮破之，水迸，儿得活。\n释义：____", "options": null}', '1. 戏：玩耍；于：在；庭：庭院。一群小孩在庭院里玩耍。\n2. 瓮：水缸；跌：失足。一个小孩爬上水缸，失足跌入水中。\n3. 皆：全都；弃：放弃；持：拿；迸：涌出。其他人都弃之而去，司马光拿着石头砸破水缸，水涌出来，小孩得以活命。', '《司马光》是小学第一篇文言文。重点字词：戏（玩耍）、于（在）、庭（庭院）、瓮（水缸）、跌（失足）、皆（全）、持（拿）、迸（涌出）。', 'paper', '"[\"文言文\", \"课文23\", \"第七单元\"]"', NULL, 0, 1);

-- q9144: node=2033 (课文24《一定要争气》)
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2033, '语文', '三年级', '填空', 2, '{"stem": "写出下列词语的近反义词。\n近义词：附近——（　　）　巡视——（　　）\n遥远——（　　）　坚硬——（　　）\n反义词：陌生——（　　）　减少——（　　）\n成功——（　　）　深入——（　　）", "options": null}', '近义词：附近——邻近；巡视——巡查；遥远——长远；坚硬——坚固\n反义词：陌生——熟悉；减少——增加；成功——失败；深入——浅显', '本题考查《一定要争气》一课的近反义词积累。', 'paper', '"[\"近反义词\", \"课文24\", \"第七单元\"]"', NULL, 0, 1);

-- q9145: node=2034 (课文25《手术台就是阵地》)
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2034, '语文', '三年级', '填空', 2, '{"stem": "根据所学，在括号内填入合适的词语。\n（　　）小庙　（　　）战士\n（　　）地取出　（　　）地赶来\n一（　　）弹片　几（　　）炮弹\n（　　）地吼叫", "options": null}', '破旧的小庙、英勇的战士、小心地取出、匆匆地赶来、一块弹片、几发炮弹、愤怒地吼叫', '本题考查《手术台就是阵地》课文词语搭配。课文写白求恩在抗日前线手术台前坚持工作。', 'paper', '"[\"词语积累\", \"课文25\", \"第七单元\"]"', NULL, 0, 1);

-- q9146: node=2035 (课文26《一个粗瓷大碗》)
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (2035, '语文', '三年级', '单选', 2, '{"stem": "给加点多音字选择正确的读音，填在括号里。\n1. 到了约定还（　）书的期限，可是我还（　）没有读完。【hái huán】\n2. 面对禁（　）令，有人严格遵守，有人却禁（　）不住诱惑。【jīn jìn】\n3. 树上结（　）满了果子，这是果农辛勤劳动的结（　）果。【jiē jié】", "options": ["A. huán, hái, jìn, jīn, jiē, jié", "B. hái, huán, jīn, jìn, jié, jiē", "C. huán, hái, jīn, jìn, jiē, jié", "D. hái, huán, jìn, jīn, jié, jiē"]}', 'C', '多音字辨析：还（huán）归还/还（hái）还有；禁（jìn）禁令/禁（jīn）禁不住；结（jiē）结果实/结（jié）结果。', 'paper', '"[\"多音字\", \"课文26\", \"第八单元\"]"', NULL, 0, 1);

